import json,hashlib,statistics,time
from pathlib import Path
import numpy as np
from scipy.stats import rankdata,spearmanr
from pymatgen.core import Structure
from rhombus.transport.cohort_audit import assess,host_steric_diagnostics
from rhombus.transport.cohort_evidence import _digest_structure
root=Path('.'); base=root/'data/benchmarks/v3_static'; old=json.loads((base/'completed_dynamics_audit_v1.json').read_text()); full=json.loads((base/'same_hash_full_comparison_v1.json').read_text()); source={r['relaxed_sha256']:r for r in full['rows']}; rows=[]; start=time.monotonic()
for item in old['structures']:
 original=source[item['relaxed_sha256']];d=json.loads(Path(original['p1_path']).read_text());raw=d['result']['relaxed_structure_dict'];assert _digest_structure(raw)==item['relaxed_sha256'];s=Structure.from_dict(raw);steric=host_steric_diagnostics(s);out={**item,**steric}; observations=[r for r in old['completed_records'] if r['relaxed_sha256']==item['relaxed_sha256']]
 if observations:
  try:
   r=assess({'path':original['p1_path'],'category':'ORDERED_EXPANSION_OR_BATCH_CANDIDATE','structure_sha256':item['relaxed_sha256'],'structure':s,'defect':{}});out['basin']=r.get('basin_diagnostic');out['basin_status']=r['status'];out['runs']=[{'p2_path':v['p2_path'],'mean_li_displacement_A':v['mean_li_displacement_A'],'production_steps':v['production_steps'],'p25_records':v['p25_records'],'temperature_K':v['temperature_K']} for v in observations];out['mean_displacement_A']=statistics.mean(v['mean_li_displacement_A'] for v in observations);out['mean_displacement_per_step_A']=statistics.mean(v['mean_li_displacement_A']/v['production_steps'] for v in observations)
  except Exception as e:out.update(basin_status='FAILED',error=repr(e))
 rows.append(out);print(len(rows),item['subset'],out.get('basin_status','-'),flush=True)
def auc(x,y):
 ranks=rankdata(x);pos=sum(y);neg=len(y)-pos
 return float((sum(rank for rank,label in zip(ranks,y) if label)-pos*(pos+1)/2)/(pos*neg))
exclusive=[r for r in rows if r['subset'] in ('COMPLETED','EXPLOSIVE')]; labels=[int(r['subset']=='COMPLETED') for r in exclusive]; stats={}
for key in ('host_min_distance_A','host_min_radius_ratio'):
 vals=[r[key] for r in exclusive];stats[key]={'auc_completion':auc(vals,labels),'spearman_completion':float(spearmanr(vals,labels).statistic),'quartiles_by_subset':{s:np.quantile([r[key] for r in exclusive if r['subset']==s],[.25,.5,.75]).tolist() for s in ('COMPLETED','EXPLOSIVE')}}
stats['threshold_1_8_A']={s:{'warning':sum(r['host_steric_collision_warning'] is True for r in exclusive if r['subset']==s),'count':sum(r['subset']==s for r in exclusive)} for s in ('COMPLETED','EXPLOSIVE')}
completed=[r for r in rows if r.get('basin_status')=='COMPUTED_UNQUALIFIED'];single=[r for r in completed if r['completed_count']==1 and not r['explosive_count']];correlations={}
for label,subset in [('single_10',single),('completed_24',completed)]:
 for metric in ('channel_ev','radius_A','x_vac_basin'):
  for target in ('mean_displacement_A','mean_displacement_per_step_A'):
   pairs=[((r['basin']['x_vac_basin'] if metric=='x_vac_basin' else r[metric]),r[target]) for r in subset if r.get('basin') is not None]; xx=[p[0] for p in pairs];yy=[p[1] for p in pairs];correlations[label+':'+metric+':'+target]={'n':len(pairs),'rho':float(spearmanr(xx,yy).statistic) if len(set(xx))>1 and len(set(yy))>1 else None}
output={'schema':'basin-steric-diagnostic-v1','source_commit':'8fb7d6132c33291f7a0b862a6beb99e93eeefa25','source_sha256':{str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in [base/'completed_dynamics_audit_v1.json',base/'same_hash_full_comparison_v1.json',Path('rhombus/transport/cohort_audit.py')]},'driver_source':Path('/tmp/rhombus_basin_analysis.py').read_text(),'rows':rows,'steric_statistics':stats,'displacement_correlations':correlations,'elapsed_seconds':time.monotonic()-start,'qualification':'ABSTAIN'}
(base/'basin_steric_diagnostic_v1.json').write_text(json.dumps(output,indent=2,sort_keys=True,allow_nan=False)+'\n');print('COMPLETE',len(rows),'completed',len(completed),'stats',stats,'correlations',correlations,flush=True)
